-- SAQR TEAM starter schema for Supabase. Run once in SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(
 id uuid primary key references auth.users(id) on delete cascade,
 discord_id text unique,
 display_name text not null default 'Member' check(char_length(display_name) between 1 and 32 and display_name !~ '\s'),
 avatar_url text,
 requested_rank text not null default 'EDITOR' check(requested_rank in('SAQR','ITS3ABDO','HEAD ADMIN','EDITOR MANAGER','ADMIN','MOD','VIP','EDITOR')),
 rank text not null default 'EDITOR' check(rank in('SAQR','ITS3ABDO','HEAD ADMIN','EDITOR MANAGER','ADMIN','MOD','VIP','EDITOR')),
 private_number text,
 xp_total bigint not null default 0 check(xp_total>=0),tasks_done integer not null default 0 check(tasks_done>=0),
 is_banned boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index if not exists profiles_xp_idx on public.profiles(xp_total desc);
create table if not exists public.chat_messages(id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 2 and 500),created_at timestamptz not null default now());
create index if not exists chat_created_idx on public.chat_messages(created_at desc);
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 100),description text not null default '',task_type text not null check(task_type in('EDITOR','ADMIN')),reward_xp integer not null check(reward_xp between 1 and 10000),target_user_id uuid references public.profiles(id) on delete set null,status text not null default 'open' check(status in('open','completed','cancelled')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.task_completions(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,reward_xp integer not null,completed_by uuid references public.profiles(id),completed_at timestamptz not null default now(),unique(task_id,user_id));
create table if not exists public.moderation_logs(id uuid primary key default gen_random_uuid(),target_user_id uuid references public.profiles(id) on delete set null,target_discord_id text not null,action text not null check(action in('ban','unban','warn')),reason text not null,moderator_id uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id),action text not null,target_user_id uuid references public.profiles(id),details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.chat_xp_cooldowns(user_id uuid primary key references public.profiles(id) on delete cascade,last_awarded_at timestamptz not null default '-infinity');

create or replace function public.is_team_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles p where p.id=auth.uid() and p.rank in('SAQR','ITS3ABDO','HEAD ADMIN') and not p.is_banned);$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into public.profiles(id,discord_id,display_name,avatar_url,requested_rank,rank) values(new.id,coalesce(new.raw_user_meta_data->>'provider_id',new.raw_user_meta_data->>'sub',new.id::text),'Member',coalesce(new.raw_user_meta_data->>'avatar_url',new.raw_user_meta_data->>'picture'),'EDITOR','EDITOR') on conflict(id) do nothing; return new; end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

alter table public.profiles enable row level security;alter table public.chat_messages enable row level security;alter table public.tasks enable row level security;alter table public.task_completions enable row level security;alter table public.moderation_logs enable row level security;alter table public.audit_logs enable row level security;alter table public.chat_xp_cooldowns enable row level security;
-- Private number is never selectable by regular clients. Admin access to it will be added through a protected Edge Function later.
revoke all on public.profiles from anon,authenticated;grant select(id,discord_id,display_name,avatar_url,requested_rank,rank,xp_total,tasks_done,is_banned,created_at,updated_at) on public.profiles to authenticated;grant update(display_name,avatar_url,requested_rank,private_number) on public.profiles to authenticated;
drop policy if exists profile_read_members on public.profiles;create policy profile_read_members on public.profiles for select to authenticated using((not is_banned) or public.is_team_admin());
drop policy if exists profile_update_own on public.profiles;create policy profile_update_own on public.profiles for update to authenticated using(id=auth.uid() and not is_banned) with check(id=auth.uid() and not is_banned);
grant select,insert on public.chat_messages to authenticated;drop policy if exists chat_read on public.chat_messages;create policy chat_read on public.chat_messages for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and not p.is_banned));drop policy if exists chat_insert on public.chat_messages;create policy chat_insert on public.chat_messages for insert to authenticated with check(user_id=auth.uid() and char_length(content) between 2 and 500 and exists(select 1 from public.profiles p where p.id=auth.uid() and not p.is_banned));
grant select,insert on public.tasks to authenticated;drop policy if exists task_read on public.tasks;create policy task_read on public.tasks for select to authenticated using((status='open' and (target_user_id is null or target_user_id=auth.uid()) and exists(select 1 from public.profiles p where p.id=auth.uid() and not p.is_banned)) or public.is_team_admin());drop policy if exists task_create on public.tasks;create policy task_create on public.tasks for insert to authenticated with check(public.is_team_admin() and created_by=auth.uid());
grant select on public.task_completions,public.moderation_logs,public.audit_logs to authenticated;drop policy if exists completions_read on public.task_completions;create policy completions_read on public.task_completions for select to authenticated using(user_id=auth.uid() or public.is_team_admin());drop policy if exists moderation_read on public.moderation_logs;create policy moderation_read on public.moderation_logs for select to authenticated using(public.is_team_admin());drop policy if exists audit_read on public.audit_logs;create policy audit_read on public.audit_logs for select to authenticated using(public.is_team_admin());

create or replace function public.award_chat_xp() returns integer language plpgsql security definer set search_path=public as $$declare awarded integer:=0;begin if not exists(select 1 from public.profiles where id=auth.uid() and not is_banned) then raise exception 'Not allowed';end if;insert into public.chat_xp_cooldowns(user_id,last_awarded_at) values(auth.uid(),'-infinity') on conflict(user_id) do nothing;update public.chat_xp_cooldowns set last_awarded_at=now() where user_id=auth.uid() and last_awarded_at<now()-interval '20 seconds';if found then update public.profiles set xp_total=xp_total+5 where id=auth.uid();awarded:=5;end if;return awarded;end;$$;
create or replace function public.admin_set_rank(target_user_id uuid,new_rank text) returns void language plpgsql security definer set search_path=public as $$declare old_rank text;begin if not public.is_team_admin() then raise exception 'Not authorized';end if;if new_rank not in('SAQR','ITS3ABDO','HEAD ADMIN','EDITOR MANAGER','ADMIN','MOD','VIP','EDITOR') then raise exception 'Invalid rank';end if;select rank into old_rank from public.profiles where id=target_user_id;update public.profiles set rank=new_rank where id=target_user_id;insert into public.audit_logs(actor_id,action,target_user_id,details) values(auth.uid(),'rank_changed',target_user_id,jsonb_build_object('old_rank',old_rank,'new_rank',new_rank));end;$$;
create or replace function public.admin_complete_task_for_user(task_id uuid,target_user_id uuid) returns void language plpgsql security definer set search_path=public as $$declare t public.tasks%rowtype;begin if not public.is_team_admin() then raise exception 'Not authorized';end if;select * into t from public.tasks where id=task_id and status='open';if not found then raise exception 'Task unavailable';end if;if t.target_user_id is not null and t.target_user_id<>target_user_id then raise exception 'Wrong target';end if;insert into public.task_completions(task_id,user_id,reward_xp,completed_by) values(t.id,target_user_id,t.reward_xp,auth.uid()) on conflict(task_id,user_id) do nothing;if not found then raise exception 'Already completed';end if;update public.profiles set xp_total=xp_total+t.reward_xp,tasks_done=tasks_done+1 where id=target_user_id and not is_banned;insert into public.audit_logs(actor_id,action,target_user_id,details) values(auth.uid(),'task_completed',target_user_id,jsonb_build_object('task_id',t.id,'reward_xp',t.reward_xp));end;$$;
create or replace function public.admin_moderate(target_discord_id text,reason_text text,action_text text) returns void language plpgsql security definer set search_path=public as $$declare target uuid;begin if not public.is_team_admin() then raise exception 'Not authorized';end if;if action_text not in('ban','unban','warn') then raise exception 'Invalid action';end if;select id into target from public.profiles where discord_id=target_discord_id;if target is null then raise exception 'Discord account not found';end if;if action_text='ban' then update public.profiles set is_banned=true where id=target;elsif action_text='unban' then update public.profiles set is_banned=false where id=target;end if;insert into public.moderation_logs(target_user_id,target_discord_id,action,reason,moderator_id) values(target,target_discord_id,action_text,reason_text,auth.uid());insert into public.audit_logs(actor_id,action,target_user_id,details) values(auth.uid(),'moderation_'||action_text,target,jsonb_build_object('reason',reason_text));end;$$;
revoke all on function public.award_chat_xp() from public;revoke all on function public.admin_set_rank(uuid,text) from public;revoke all on function public.admin_complete_task_for_user(uuid,uuid) from public;revoke all on function public.admin_moderate(text,text,text) from public;grant execute on function public.award_chat_xp() to authenticated;grant execute on function public.admin_set_rank(uuid,text),public.admin_complete_task_for_user(uuid,uuid),public.admin_moderate(text,text,text) to authenticated;
-- Enable chat_messages in Supabase Database > Replication for realtime updates.
-- After the first OAuth sign-in, promote your own profile from SQL Editor:
-- update public.profiles set rank='SAQR' where id='YOUR-AUTH-USER-UUID';
-- Discord provider must be configured in Supabase Auth. Bot/Discord role verification is intentionally deferred.
